const targetNames=vi.hoisted(()=>vi.fn())
vi.mock('../../src/features/rules/task-choices',async()=>({...await vi.importActual<typeof import('../../src/features/rules/task-choices')>('../../src/features/rules/task-choices'),selectedTaskChoices:targetNames}))
const api = vi.hoisted(() => ({ getTask: vi.fn(), saveTaskInformation: vi.fn(), saveTaskContent: vi.fn(),enableTask:vi.fn(),disableTask:vi.fn(), getTaskUsageStatistics: vi.fn(), taskExecutions: vi.fn() }))
