 for(const id of ['null','"1"','true','1.5','1.0','1e3','9007199254740992','-9007199254740992'])expect(()=>taskCommandValue('{"method":"set","params":{},"id":'+id+'}')).toThrow('id')
 expect(()=>taskCommandValue('{"method":"set","params":{},"id":1,"id":2}')).toThrow('重复')
