it('OTA任务创建到详情保双字段、目录自由输入与取消，未知按原键和完整CAS只读恢复',async()=>{
 const project='10000000-0000-4000-8000-000000000001',device='20000000-0000-4000-8000-000000000001',id='30000000-0000-4000-8000-000000000001'
 session.user={...session.user!,currentProjectId:project};session.projects=[{id:project,status:'ACTIVE',timezone:'Asia/Shanghai'}]
 let saved:Schema<'TaskJobResponse'>,catalogFailed=false
 let otaResult:Schema<'TaskLogDeviceItem'>['otaUpgrade']={decisionId:id,decision:'ACCEPTED',reason:null,observedVersion:'1.0',firmwareId:id,targetVersion:'2.0',campaignId:id,jobId:id,jobStatus:'PENDING',terminal:false}
 const transport={create:vi.fn().mockImplementation(async(_p:string,_d:string,body:Schema<'SaveTaskJobRequest'>)=>{saved={...body,id,actionType:'OTA_UPGRADE',commandKey:null,status:'PAUSED',version:1,tags:{},createdAt:'2026-11-03T00:00:00Z',updatedAt:'2026-11-03T00:00:00Z'};throw new ApiError('结果未知',0,undefined,undefined,true)}),definition:vi.fn().mockImplementation(async()=>saved),creation:vi.fn().mockResolvedValue({jobId:id,initialDefinitionVersion:1,deleted:false}),preference:vi.fn().mockResolvedValue({deviceId:device,allowed:true,version:1,definitionVersion:1}),change:vi.fn(),read:vi.fn(),run:vi.fn()}
 const send=vi.spyOn(http,'api').mockImplementation(async(path:string,options:http.RequestOptions={})=>{
  if(path.endsWith('/app-visibility'))return {taskId:id,version:4,projectDeviceDetails:false,userSettings:false,userDetails:false}
  if(path.endsWith(`/task-debug-logs/${id}/devices`))return {logId:id,jobId:id,executionId:id,executionStartedAt:'2026-11-03T00:00:00Z',deviceCount:1,items:[{deviceId:device,deviceName:'实际目标',deviceReadable:true,targetStatus:'ACCEPTED',acceptedAt:'2026-11-03T00:00:00Z',completedAt:null,...(otaResult?{otaUpgrade:otaResult}:{})}],nextCursor:null,hasMore:false}
  expect(path).toBe(`/api/v1/projects/${project}/task-ota-version-attributes/selections`);expect(options).toMatchObject({method:'post',body:{targetType:'EXPLICIT_DEVICES',targetDeviceIds:[device],search:'ver',limit:50}});expect(options.body).not.toHaveProperty('input');if(catalogFailed)throw new ApiError('候选暂不可读',503);return {items:[{identifier:'version_attr',name:'版本号'}],hasMore:false}
 })
 try{
  const router=createRouter({history:createMemoryHistory(),routes:ruleRoutes});await router.push('/tasks/jobs/create');await router.isReady();wrapper=mount(DeviceTaskCreateForm,{props:{deviceId:device,deviceName:'实际目标',transport,stepped:true},global:{plugins:[router],stubs}});await flushPromises()
  await wrapper.get('[aria-label="新任务名称"]').setValue('OTA任务');wrapper.getComponent(ElRadioGroup).vm.$emit('update:modelValue','COMMAND');await flushPromises();await button('配置OTA推送').trigger('click');await flushPromises();let dialog=wrapper.getComponent(TaskOtaUpgradeDialog)
  const autocomplete=()=>dialog.getComponent({name:'ElAutocomplete'})
  autocomplete().vm.$emit('update:modelValue','discarded');await flushPromises();await button('取消').trigger('click');await button('配置OTA推送').trigger('click');await flushPromises();dialog=wrapper.getComponent(TaskOtaUpgradeDialog);expect(autocomplete().props('modelValue')).toBe('');expect((wrapper.get('[aria-label="OTA模块"]').element as HTMLInputElement).value).toBe('main')
  let suggested:unknown;await autocomplete().props('fetchSuggestions')('ver',(rows:unknown)=>{suggested=rows});expect(suggested).toEqual([{value:'version_attr',name:'版本号'}]);catalogFailed=true;await autocomplete().props('fetchSuggestions')('ver',()=>{});await flushPromises();expect(wrapper.text()).toContain('版本属性建议暂不可用')
  autocomplete().vm.$emit('update:modelValue','version_attr');await flushPromises();await button('完成').trigger('click');await flushPromises();expect(transport.create).not.toHaveBeenCalled();await button('下一步').trigger('click');await flushPromises();await wrapper.get('[aria-label="新任务描述"]').setValue('OTA描述');await button('创建').trigger('click');await flushPromises()
  expect(transport.create).toHaveBeenCalledTimes(1);expect(transport.create.mock.lastCall![2]).toMatchObject({name:'OTA任务',description:'OTA描述',actionType:'OTA_UPGRADE',commandKey:null,input:{versionProperty:'version_attr',module:'main'},targetType:'EXPLICIT_DEVICES',targetDeviceIds:[device],timezone:'Asia/Shanghai',scheduleType:'MANUAL',enabled:false});expect(transport.create.mock.lastCall![2]).not.toHaveProperty('commandRequestId');expect(transport.create.mock.lastCall![2].input).not.toHaveProperty('firmwareId');expect(button('创建').attributes('disabled')).toBeDefined()
  session.user={...session.user!,permissions:['task:read']};await flushPromises();expect(wrapper.find('[aria-label="新任务名称"]').exists()).toBe(true);expect(wrapper.text()).not.toContain('OTA描述');const originalKey=transport.create.mock.lastCall![3];transport.definition.mockResolvedValueOnce({...saved!,input:{versionProperty:'wrong',module:'main'}});await button('重新读取核对').trigger('click');await flushPromises();expect(button('下一步').attributes('disabled')).toBeDefined();expect(transport.create).toHaveBeenCalledTimes(1);await button('重新读取核对').trigger('click');await flushPromises();expect(transport.creation).toHaveBeenCalledWith(project,originalKey,expect.any(AbortSignal));expect(wrapper.emitted('created')).toEqual([[id]]);session.user={...session.user!,permissions:['task:read','task:manage']};await flushPromises()
  wrapper.unmount();saved={...saved!,version:4,tags:{已存:'保留'}};api.getTask.mockImplementation(async()=>saved);await router.push(`/tasks/jobs/${id}`);wrapper=mount(RouterView,{global:{plugins:[router],stubs}});await flushPromises();expect(wrapper.get('.task-content-card').text()).toContain('命令下发');expect(wrapper.get('.task-content-card').text()).toContain('OTA 推送');expect(wrapper.get('.task-content-card').text()).toContain('version_attr');expect(wrapper.get('.task-content-card').find('pre').exists()).toBe(false)
  await button('编辑任务内容').trigger('click');dialog=wrapper.getComponent(TaskOtaUpgradeDialog);expect(dialog.props('value')).toEqual({versionProperty:'version_attr',module:'main'});autocomplete().vm.$emit('update:modelValue','cancelled');await flushPromises();await button('取消').trigger('click');expect(api.saveTaskContent).not.toHaveBeenCalled();await button('编辑任务内容').trigger('click');dialog=wrapper.getComponent(TaskOtaUpgradeDialog);expect(autocomplete().props('modelValue')).toBe('version_attr')
  autocomplete().vm.$emit('update:modelValue','next_version');await flushPromises();api.saveTaskContent.mockRejectedValueOnce(new ApiError('结果未知',0,undefined,undefined,true));await button('完成').trigger('click');await flushPromises();expect(api.saveTaskContent).toHaveBeenCalledExactlyOnceWith(project,id,expect.objectContaining({actionType:'OTA_UPGRADE',commandKey:null,input:{versionProperty:'next_version',module:'main'},expectedVersion:4,targetType:'EXPLICIT_DEVICES',targetDeviceIds:[device],scheduleType:'MANUAL',timezone:'Asia/Shanghai',enabled:false}));expect(api.saveTaskContent.mock.lastCall![2]).not.toHaveProperty('tags');expect(button('取消').attributes('disabled')).toBeDefined();expect(button('完成').attributes('disabled')).toBeDefined()
  api.getTask.mockResolvedValueOnce({...saved,input:{versionProperty:'wrong',module:'main'},version:5});await button('重新读取核对').trigger('click');await flushPromises();expect(autocomplete().props('modelValue')).toBe('next_version');expect(button('完成').attributes('disabled')).toBeDefined();session.user={...session.user!,permissions:['task:read']};await flushPromises();expect(wrapper.find('[role="dialog"]').exists()).toBe(false);api.getTask.mockResolvedValueOnce({...saved,input:{versionProperty:'next_version',module:'main'},version:5});await button('重新读取核对').trigger('click');await flushPromises();expect(wrapper.find('[role="dialog"]').exists()).toBe(false);expect(wrapper.get('.task-content-card').text()).toContain('next_version');expect(api.saveTaskContent).toHaveBeenCalledTimes(1);expect(transport.create).toHaveBeenCalledTimes(1);expect(send.mock.calls.filter(([path])=>path.endsWith('/task-ota-version-attributes/selections'))).toHaveLength(2)
  const readResult=()=>taskDebugLogTransport.readDevices!(project,id,undefined,new AbortController().signal)
  expect((await readResult()).rows[0]).toMatchObject({otaLabel:'升级已受理',otaVersion:'原版本：1.0；目标版本：2.0'})
  otaResult={...otaResult!,jobStatus:'SUCCEEDED',terminal:true};expect((await readResult()).rows[0]?.otaLabel).toBe('升级成功')
  otaResult={...otaResult!,decision:'NO_UPDATE',firmwareId:null,targetVersion:null,campaignId:null,jobId:null,jobStatus:null,terminal:true};expect((await readResult()).rows[0]?.otaLabel).toBe('无需升级')
  otaResult={...otaResult!,decision:'REJECTED',reason:'REPORT_MISSING'};expect((await readResult()).rows[0]?.otaLabel).toBe('升级未受理：缺少设备版本报告')
  otaResult={...otaResult!,reason:'UNRECOGNIZED_REASON'};expect((await readResult()).rows[0]?.otaLabel).toBe('升级未受理')
  otaResult=undefined;expect((await readResult()).rows[0]).not.toHaveProperty('otaLabel')
 }finally{session.projects=[]}
})
